"use server";

import { revalidatePath } from "next/cache";

import { db } from "@/db";
import { documents } from "@/db/schema";
import { requireUser } from "@/lib/auth";
import { convertUpload, ImportError } from "@/lib/import/convert";

export type ImportState =
  | { ok: true; id: string; title: string; removed: string[] }
  | { ok: false; error: string };

export const importDocument = async (
  formData: FormData
): Promise<ImportState> => {
  const user = await requireUser();
  const file = formData.get("file");
  if (!(file instanceof File)) {
    return { error: "Choose a file to import.", ok: false };
  }

  try {
    const { content, removed, title } = await convertUpload(file);
    const [doc] = await db
      .insert(documents)
      .values({ content, ownerId: user.id, title })
      .returning({ id: documents.id });
    revalidatePath("/");
    return { id: doc.id, ok: true, removed, title };
  } catch (error) {
    if (error instanceof ImportError) {
      return { error: error.message, ok: false };
    }
    console.error("Import failed", error);
    return {
      error: "Something went wrong importing that file. Please try again.",
      ok: false,
    };
  }
};

"use client";

import { FileUpIcon, Loader2Icon } from "lucide-react";
import { useRouter } from "next/navigation";
import { useRef, useTransition } from "react";
import { toast } from "sonner";

import { importDocument } from "@/app/documents/actions";
import { Button } from "@/components/ui/button";

const MAX_BYTES = 4 * 1024 * 1024;
const ACCEPT = ".docx,.md,.markdown,.txt";

export const ImportButton = () => {
  const inputRef = useRef<HTMLInputElement>(null);
  const router = useRouter();
  const [pending, startTransition] = useTransition();

  const onFile = (file: File) => {
    // Checked again on the server; this just saves a pointless upload.
    if (file.size > MAX_BYTES) {
      toast.error("That file is larger than 4 MB.");
      return;
    }
    const formData = new FormData();
    formData.set("file", file);

    startTransition(async () => {
      const result = await importDocument(formData);
      if (!result.ok) {
        toast.error(result.error);
        return;
      }
      if (result.removed.length > 0) {
        toast.warning(`Imported “${result.title}”`, {
          description: `${result.removed.join(". ")}. The editor only keeps headings, bold, italic, underline and lists.`,
          duration: 10_000,
        });
      } else {
        toast.success(`Imported “${result.title}”`);
      }
      router.push(`/d/${result.id}`);
    });
  };

  return (
    <>
      <input
        accept={ACCEPT}
        className="hidden"
        onChange={(event) => {
          const file = event.target.files?.[0];
          event.target.value = "";
          if (file) {
            onFile(file);
          }
        }}
        ref={inputRef}
        type="file"
      />
      <Button
        disabled={pending}
        onClick={() => inputRef.current?.click()}
        variant="outline"
      >
        {pending ? (
          <Loader2Icon className="animate-spin" />
        ) : (
          <FileUpIcon />
        )}
        {pending ? "Importing…" : "Import file"}
      </Button>
    </>
  );
};

