      onFocus={(event) => {
        if (autoFocus) {
          event.target.select();
        }
      }}
      onKeyDown={(event) => {
        if (event.key === "Enter") {
          event.preventDefault();
          event.currentTarget.blur();
          onDone?.();
        }
        if (event.key === "Escape") {
          setTitle(saved.current);
          event.currentTarget.blur();
        }
      }}
      value={title}
    />
  );
};

