"use client";

import type { Editor } from "@tiptap/core";
import { useCallback, useEffect, useRef, useState } from "react";

import { saveDocument } from "@/app/documents/actions";

const DEBOUNCE_MS = 1000;

export type SaveStatus =
  | { kind: "saved"; at: string | null }
  | { kind: "unsaved" }
  | { kind: "saving" }
  | { kind: "error"; message: string }
  | { kind: "conflict"; editedBy: string | null };

const FAILURE_MESSAGES = {
  invalid: "This change couldn't be saved.",
  "not-found": "You no longer have access to this document.",
  "signed-out": "You've been signed out. Sign in again to keep saving.",
} as const;

/**
 * Debounced autosave with optimistic concurrency. Saves at most one request at
 * a time; edits made while a save is in flight are saved right after it.
 */
export const useAutosave = ({
  editor,
  documentId,
  initialVersion,
  initialSavedAt,
}: {
  editor: Editor | null;
  documentId: string;
  initialVersion: number;
  initialSavedAt: string;
}) => {
  const [status, setStatus] = useState<SaveStatus>({
    at: initialSavedAt,
    kind: "saved",
  });
  const version = useRef(initialVersion);
  const dirty = useRef(false);
  const inFlight = useRef(false);
  const stopped = useRef(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const save = useCallback(async () => {
    if (timer.current) {
      clearTimeout(timer.current);
      timer.current = null;
    }
    if (!editor || stopped.current || inFlight.current || !dirty.current) {
      return;
    }

    dirty.current = false;
    inFlight.current = true;
    setStatus({ kind: "saving" });

    try {
      const result = await saveDocument({
        baseVersion: version.current,
        content: editor.getJSON(),
        id: documentId,
      });

      if (result.ok) {
        version.current = result.version;
        if (dirty.current) {
          setStatus({ kind: "unsaved" });
        } else {
          setStatus({ at: result.savedAt, kind: "saved" });
        }
      } else if (result.reason === "conflict") {
        // Stop here: keep what the user typed on screen, but never overwrite
        // the other person's version.
        stopped.current = true;
        dirty.current = true;
        editor.setEditable(false);
        setStatus({ editedBy: result.editedBy, kind: "conflict" });
      } else {
        dirty.current = true;
        setStatus({ kind: "error", message: FAILURE_MESSAGES[result.reason] });
      }
    } catch {
      dirty.current = true;
      setStatus({
        kind: "error",
        message: "Couldn't reach the server. Your changes are kept here.",
      });
    } finally {
      inFlight.current = false;
    }

    // Edits that arrived during the request.
    if (dirty.current && !stopped.current && !timer.current) {
      timer.current = setTimeout(save, DEBOUNCE_MS);
    }
  }, [editor, documentId]);

  // Schedule a save after each change.
  useEffect(() => {
    if (!editor) {
      return;
    }
    const onUpdate = () => {
      if (stopped.current) {
        return;
      }
      dirty.current = true;
      setStatus((current) =>
        current.kind === "error" ? current : { kind: "unsaved" }
      );
      if (timer.current) {
        clearTimeout(timer.current);
      }
      timer.current = setTimeout(save, DEBOUNCE_MS);
    };
    editor.on("update", onUpdate);
    return () => {
      editor.off("update", onUpdate);
    };
  }, [editor, save]);

  // Save immediately when the tab is hidden; warn before leaving with unsaved
  // changes; Cmd/Ctrl+S saves now instead of opening the browser dialog.
  useEffect(() => {
    const onHide = () => {
      if (document.visibilityState === "hidden") {
        save();
      }
    };
    const onBeforeUnload = (event: BeforeUnloadEvent) => {
      if ((dirty.current || inFlight.current) && !stopped.current) {
        event.preventDefault();
      }
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "s") {
        event.preventDefault();
        save();
      }
    };
    document.addEventListener("visibilitychange", onHide);
    window.addEventListener("beforeunload", onBeforeUnload);
    window.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("visibilitychange", onHide);
      window.removeEventListener("beforeunload", onBeforeUnload);
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [save]);

  useEffect(
    () => () => {
      if (timer.current) {
        clearTimeout(timer.current);
      }
    },
    []
  );

  /** Lets the page reload without the unsaved-changes prompt. */
  const discard = useCallback(() => {
    stopped.current = true;
    dirty.current = false;
  }, []);

  return { discard, retry: save, status };
};

